CREATE COLUMN TABLE "TEST_AP"."ADNF" ("AbsEntry" INTEGER CS_INT NOT NULL , "NCMEntry" INTEGER CS_INT NOT NULL , "DNFCode" NVARCHAR(5) NOT NULL , "DNFUoM" NVARCHAR(10), "DNFFactor" DECIMAL(21,6) CS_FIXED, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ADNF_NCM_DNF" ON "TEST_AP"."ADNF" ( "NCMEntry" ASC, "DNFCode" ASC, "LogInstanc" ASC )